manifests.package.json:
{
  "packageManager": "yarn@4.18.0",
  "name": "woodenlist",
  "version": "0.1.1",
  "description": "A realtime todolist",
  "main": "index.js",
  "engines": {
    "node": ">=24"
  },
  "scripts": {
    "check": "yarn check-client && yarn check-server",
    "check-client": "calcit calcit.cirru --check-only --ns 'app.$meta' --ns app.client --ns app.comp.container --ns app.comp.done-tasks --ns app.comp.home --ns app.comp.login --ns app.comp.pending --ns app.comp.profile --ns app.comp.sidebar --ns app.config --ns app.schema --ns app.style",
    "check-server": "calcit calcit.cirru --entry server --check-only --ns 'app.$meta' --ns app.config --ns app.schema --ns app.server --ns app.twig.container --ns app.twig.user --ns app.updater --ns app.updater.router --ns app.updater.session --ns app.updater.task --ns app.updater.user",
    "compile-page": "calcit calcit.cirru js",
    "release-page": "vite build --base=${VITE_BASE_URL:-./}",
    "server": "calcit calcit.cirru --entry server",
    "watch-page": "calcit calcit.cirru js --watch"
  },
  "repository": {
    "type": "git",
    "url": "git@github.com:TopixIM/woodenlist.git"
  },
  "author": "jiyinyiyong",
  "license": "MIT",
  "dependencies": {
    "@calcit/procs": "0.30.1-alpha.5",
    "cirru-color": "^0.2.4",
    "copy-text-to-clipboard": "^3.2.1",
    "dayjs": "^1.11.18",
    "nanoid": "^5.1.5"
  },
  "devDependencies": {
    "bottom-tip": "^0.1.5",
    "feather-icons": "^4.29.2",
    "vite": "^8.2.4"
  }
}
